-- Candidate for a coordinated production update. This only becomes active as
-- part of the single transaction generated by build-production-rollout.mjs.
-- The caller must independently verify project identity and backup freshness.
DO $$
DECLARE p oid := to_regprocedure('public.reset_turma_journey(uuid)');
BEGIN
  IF md5(replace(pg_get_functiondef(to_regprocedure('public.save_lesson_draft(uuid,jsonb,boolean,boolean)')),E'\r\n',E'\n')) IS DISTINCT FROM '4c28d8a62bb396d7fad6c0220b6fc7a4'
     OR md5(replace(pg_get_functiondef(to_regprocedure('public.complete_lesson(uuid,jsonb,boolean,boolean,integer,uuid)')),E'\r\n',E'\n')) IS DISTINCT FROM '6a9bbfb1f4ef8555aa3cfe9acd4b502c'
     OR md5(replace(pg_get_functiondef(to_regprocedure('public.complete_devotional(uuid,jsonb,boolean,integer,uuid)')),E'\r\n',E'\n')) IS DISTINCT FROM 'e1aff0837e86e689e5a7e4d92074b333'
     OR md5(replace(pg_get_functiondef(p),E'\r\n',E'\n')) IS DISTINCT FROM 'aa626632b6b808d6d2ac410648bfa681' THEN
    RAISE EXCEPTION 'PRODUCTION_FUNCTION_VERSION_MISMATCH';
  END IF;
  IF NOT has_function_privilege('authenticated',p,'EXECUTE')
     OR NOT has_function_privilege('service_role',p,'EXECUTE')
     OR EXISTS(SELECT 1 FROM pg_proc f CROSS JOIN LATERAL aclexplode(f.proacl) a
       WHERE f.oid=p AND a.privilege_type='EXECUTE'
       AND a.grantee NOT IN (f.proowner,'authenticated'::regrole::oid,'service_role'::regrole::oid)) THEN
    RAISE EXCEPTION 'PRODUCTION_RESET_GRANTS_MISMATCH';
  END IF;
  IF to_regclass('private.production_policy_snapshot_20261124') IS NOT NULL
     OR to_regclass('private.production_release_snapshot_20261124') IS NOT NULL
     OR to_regprocedure('private.production_release_fingerprints_20261124()') IS NOT NULL
     OR to_regclass('private.production_worship_receipts_archive_20261124') IS NOT NULL
     OR to_regclass('private.completion_review_events') IS NOT NULL
     OR to_regclass('private.completion_review_events_archive_20261125') IS NOT NULL
     OR to_regclass('private.completion_review_archive_20261125') IS NOT NULL
     OR to_regclass('private.completion_review_requests') IS NOT NULL
     OR to_regclass('private.learning_membership_version_archive_20261125') IS NOT NULL
     OR to_regclass('private.learning_membership_version') IS NOT NULL
     OR to_regprocedure('public.get_owned_learning_scope(uuid)') IS NOT NULL
     OR to_regprocedure('private.rotate_learning_membership_version()') IS NOT NULL
     OR to_regclass('private.learning_write_guard') IS NOT NULL
     OR to_regclass('private.attendance_write_guard') IS NOT NULL
     OR to_regclass('private.worship_write_guard') IS NOT NULL
     OR to_regclass('private.offline_worship_receipts') IS NOT NULL
     OR EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
       WHERE n.nspname='public' AND NOT t.tgisinternal AND t.tgname IN ('aa_lock_learning_write','aa_guard_own_final_attendance','aa_guard_own_worship_insert')) THEN
    RAISE EXCEPTION 'PRODUCTION_OBJECT_COLLISION';
  END IF;
END $$;
CREATE TABLE private.production_policy_snapshot_20261124 AS
SELECT tablename, policyname, permissive, roles, cmd, qual, with_check
FROM pg_catalog.pg_policies WHERE schemaname='public'
 AND tablename IN ('lesson_responses','devotional_responses','lesson_progress','devotional_progress');
ALTER TABLE private.production_policy_snapshot_20261124 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.production_policy_snapshot_20261124 FROM PUBLIC,anon,authenticated;
